head.script:
scwin.fn_GetPar, scwin.fn_SetPar = "";
scwin.gDepCd;

///////// 2. 초기화 영역 /////////
/**
 * @method
 * @name onpageload
 * @description 화면 로딩 시 초기 처리 — init 순차 호출
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.onpageload = async function() {
    try {
        edt_BASE_DD.setValue($c.ut.cGetToday("yyyymmdd")); // 현재날짜

        // round처리
        $c.libRoundPanel.PanelToGroupBox(panel_Top);
        await scwin.setCode();
        await scwin.searchCode();
        scwin.init();

        // 초기로딩시 3개 칼럼만 표시한다.
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF24700.onpageload" });
    }
};

/**
 * @method
 * @name onpageunload
 * @description 화면 언로드 시 정리 처리
 * @returns {void}
 * @hidden N
 */
scwin.onpageunload = function() {
};

/**
 * @method
 * @name init
 * @description 화면 초기화 — 파라미터 수신·기본값·컴포넌트 초기 설정(onpageload 에서 순차 호출)
 * @returns {void}
 * @hidden N
 */
scwin.init = function() {
    scwin.changeETPPRODTPCD();
};

///////// 3. 컴포넌트 이벤트 영역 /////////
/**
 * @method
 * @name dts_List_OnLoadCompleted
 * @description dts_List 로드 완료 후처리(레거시 Gauce 이벤트명 — 화면 내부 호출용)
 * @param {Number} rowcount 조회 건수
 * @returns {void}
 * @hidden N
 */
scwin.dts_List_OnLoadCompleted = function(rowcount) {
    try {
        $c.stf.fillGridHeaderTotalCnt(rowcount, panel_page);
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDSTF24700.dts_List_OnLoadCompleted" });
    }
};

/**
 * @method
 * @name dts_List_OnLoadError
 * @description dts_List 로드 오류 처리(레거시 Gauce 이벤트명 — 화면 내부 호출용)
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.dts_List_OnLoadError = async function() {
    try {
        await $c.win.alert(dts_List);
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF24700.dts_List_OnLoadError" });
    }
};

/**
 * @method
 * @name img_BASE_DD_onclick
 * @description img_BASE_DD 클릭 이벤트
 * @returns {void}
 * @hidden N
 */
