    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDSTF24700.img_BASE_DD_onclick" });
    }
};

/**
 * @method
 * @name dts_small_ind_OnFilter
 * @description small ind On Filter 처리
 * @param {Number} row 행 인덱스
 * @returns {void}
 * @hidden N
 */
scwin.dts_small_ind_OnFilter = function(row) {
    try {
        //  중분류에 해당하는 소분류를 보여준다.
        if (gInd === "%") {
            // 전체일 경우 모두 보여준다.
            return true;
        } else {
            const s_ind = dts_small_ind.getCellData(row, "VALUE");
            // alert(s_ind);
            if (s_ind.substring(0, 4) === gInd || dts_small_ind.getCellData(row, "VALUE") === "%") {
                return true;
            } else {
                return false;
            }
        }
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDSTF24700.dts_small_ind_OnFilter" });
    }
};

