    try {
        $c.stf.doLogSave("ULDSTF24700.xml", SCREN_PROCS_TP_CD_07); // 엑셀
        if (dts_List.getRowCount() > 0) {
            $c.data.downloadGridViewExcel(grd_List, {fileName: "ETF/ETN 조검별 검색", type: 1}); // show false인것은 안보여준다.(type = 1)

        }
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDSTF24700.img_Excel_onclick" });
    }
};

