///////// 4. 서브미션 콜백 영역 /////////
/**
 * @method
 * @name listSync
 * @description 기준일자 지정검색
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.listSync = async function() {
    /*
    if ( getObjectValue(edt_BASE_DD) > cGetToday("yyyymmdd")) {
    	alert("기준일이 현재일보다 큽니다.");
    	edt_BASE_DD.focus();
    	return;
    }
     */

    url += "?SCREN_ID=" + "ULDSTF24700.xml" + "&SCREN_PROCES_TP_CD=" + SCREN_PROCS_TP_CD_01;
