/**
 * @method
 * @name searchCode
 * @description 검색 조건 콤보박스
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.searchCode = async function() {
    /*
    상품유형 			ETP_PROD_TP_CD
    지수산출기관 	IDX_CALC_INST_CD
    레버리지				IDX_LVRG_INVRS_TP_CD
    복제방법				ETF_REPLICA_METHD_TP_CD
     */
    const arrCid = [{
        cid: "ETP_PROD_TP_CD",
        cnm: "cmb_ETP_PROD_TP_CD"
    }, {
        cid: "IDX_CALC_INST_CD",
        cnm: "cmb_IDX_CALC_INST_CD"
    }, {
        cid: "IDX_LVRG_INVRS_TP_CD",
        cnm: "cmb_IDX_LVRG_INVRS_TP_CD"
    }, {
        cid: "ETF_REPLICA_METHD_TP_CD",
        cnm: "cmb_ETF_REPLICA_METHD_TP_CD"
    }, {
        cid: "LOSS_LMT_ETN_EARNG_STRUCT_CD",
        cnm: "cmb_EARNG_STRUCT_TP_CD"
    }];
    let objCod;
    const sbmOptions = {
        id : "sbm_dts_Cod",
        action : "/CodeAction.do",
        ref : "",
        target : "dts_Cod=body.content",
        isProcessMsg : false
    };

    const sbmRtn = await $c.sbm.executeDynamic(sbmOptions);
    // TODO Stage2: sbmRtn 응답 처리 로직 작성 (구 submitDoneHandler 자리)

    let strCbd = "",
        i, j;
    for (i = 0; i < arrCid.length; i++) {
        objCod = document.getElementById(arrCid[i].cnm);
        // alert('[objCod]'+objCod);
        if (objCod === null) {
            await $c.win.alert(arrCid[i].cnm);
        }
        strCbd = "^전체";
        for (j = 1; j <= dts_Cod.getRowCount(); j++) {
            if (dts_Cod.getCellData(j, "CD_ENG_NM") === arrCid[i].cid) {
                strCbd = strCbd + (strCbd === "" ? "" : ",") + dts_Cod.getCellData(j, "VALUE") + "^" + dts_Cod.getCellData(j, "TEXT");
            }
        }
        objCod.CBData = strCbd;
    }
};

///////// 5. 일반/업무 함수 영역 /////////
/**
 * @method
 * @name chkOnclick
 * @description 표출 항목 체크박스 이벤트 처리
 * @param {String} columnId 컬럼 id
 * @returns {void}
 * @hidden N
 */
scwin.chkOnclick = function(columnId) {
    const isView = $c.cm.getColumnProp(grd_List, columnId, "Show");
    if (isView) {
        $c.cm.setColumnProp(grd_List, columnId, "Show", "false");
    }
    if (isView === "FALSE") {
        $c.cm.setColumnProp(grd_List, columnId, "Show", "true");
    }
};

/**
 * @method
 * @name onStepComboSelChange
 * @description 상위-하위 콤보박스 값 연동
 * @param {*} pValue pValue
 * @param {*} dst dst
 * @param {*} targetObj targetObj
 * @param {String} targetPValueNm targetPValueNm
 * @returns {void}
 * @hidden N
 */
scwin.onStepComboSelChange = function(pValue, dst, targetObj, targetPValueNm) {
    let strCbd = "^전체";
    targetObj.CBData = strCbd;
    if (!(pValue === "" || pValue === null)) {
        for (j = 1; j <= dst.getRowCount(); j++) {
            // alert(dst.NameValue(j, "TEXT")) ;
            if (dst.getCellData(j, targetPValueNm) === pValue) {
                strCbd += (strCbd === "" ? "" : ",") + dst.getCellData(j, "VALUE") + "^" + dst.getCellData(j, "TEXT");
            }
        }
        targetObj.CBData = strCbd;
        targetObj.ResetData();
        // alert( "CountRow="+targetObj.CountRow) ;

    }
};

/**
 * @method
 * @name changeETPPRODTPCD
 * @description 상품유형 선택 시
 * @returns {void}
 * @hidden N
 */
scwin.changeETPPRODTPCD = function() {
    const vETP_PROD_TP_CD = cmb_ETP_PROD_TP_CD.getValue();
    if (vETP_PROD_TP_CD === '4') {
        // 손실제한 ETN 선택 시
        cmb_EARNG_STRUCT_TP_CD.setDisabled(false); // 수익구조유형

    } else {
        cmb_EARNG_STRUCT_TP_CD.setDisabled(true);
        cmb_EARNG_STRUCT_TP_CD.setValue("전체");
    }
};
